"""Generate the refactored app.py and the adapter regression test file.

Extracts the ground-truth endpoint contract (path, endpoint name, key-set
constant, policy operation, positional request fields, valid-wrap) from the
current app.py via AST, then emits:

- regulation_policy_compiler/app.py with a shared _policy_response adapter
- tests/test_policy_http_adapter.py with a parametrized regression suite
"""

import ast
import json
from pathlib import Path

ROOT = Path("/ddb/cap1/ca/task091")
APP_PATH = ROOT / "regulation_policy_compiler" / "app.py"
TEST_PATH = ROOT / "tests" / "test_policy_http_adapter.py"

source = APP_PATH.read_text()
tree = ast.parse(source)

policy_names = set()
for node in tree.body:
    if isinstance(node, ast.ImportFrom) and node.module == "policy":
        policy_names = {alias.name for alias in node.names}

key_sets = {}
for node in tree.body:
    if (
        isinstance(node, ast.Assign)
        and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id.endswith("_KEYS")
    ):
        key_sets[node.targets[0].id] = set(ast.literal_eval(node.value))

specs = []
for node in tree.body:
    if not isinstance(node, ast.AsyncFunctionDef):
        continue
    path = None
    for dec in node.decorator_list:
        if (
            isinstance(dec, ast.Call)
            and isinstance(dec.func, ast.Attribute)
            and dec.func.attr == "post"
            and isinstance(dec.func.value, ast.Name)
            and dec.func.value.id == "app"
        ):
            path = ast.literal_eval(dec.args[0])
    if path is None:
        continue
    keys_var = None
    for sub in ast.walk(node):
        if (
            isinstance(sub, ast.Compare)
            and isinstance(sub.left, ast.Call)
            and isinstance(sub.left.func, ast.Name)
            and sub.left.func.id == "set"
            and len(sub.comparators) == 1
            and isinstance(sub.comparators[0], ast.Name)
        ):
            keys_var = sub.comparators[0].id
    op_name = None
    fields = ()
    for stmt in node.body:
        if not isinstance(stmt, ast.Try):
            continue
        for inner in stmt.body:
            if not (isinstance(inner, ast.Assign) and isinstance(inner.value, ast.Call)):
                continue
            call = inner.value
            if not isinstance(call.func, ast.Name):
                continue
            if call.func.id not in policy_names:
                continue
            op_name = call.func.id
            fields = tuple(ast.literal_eval(arg.slice) for arg in call.args)
    if op_name is None:
        continue
    wrap = False
    for stmt in node.body:
        if isinstance(stmt, ast.Return) and isinstance(stmt.value, ast.Call):
            call = stmt.value
            if isinstance(call.func, ast.Name) and call.func.id == "_record_response":
                if isinstance(call.args[0], ast.Dict):
                    wrap = True
    assert keys_var is not None, node.name
    assert set(fields) == key_sets[keys_var], (node.name, fields, keys_var)
    specs.append((path, node.name, keys_var, op_name, fields, wrap))

print(f"extracted {len(specs)} policy endpoints")
assert len(specs) == 58
assert len({s[1] for s in specs}) == 58
assert len({s[0] for s in specs}) == 58

# ---------------------------------------------------------------- app.py

LIMIT = 79


def path_chunks(path, width=70):
    segs = path.split("/")[1:]
    tokens = [s + "/" for s in segs[:-1]] + [segs[-1]]
    chunks = []
    current = ""
    for token in tokens:
        if current and len(current) + len(token) > width:
            chunks.append(current)
            current = ""
        current += token
    chunks.append(current)
    return chunks


def fields_literal(fields):
    inner = ", ".join(f'"{f}"' for f in fields)
    if len(fields) == 1:
        inner += ","
    return f"({inner})"


def emit_endpoint(spec):
    path, name, keys_var, op_name, fields, wrap = spec
    lines = []
    decorator = f'@app.post("{path}")'
    if len(decorator) <= LIMIT:
        lines.append(decorator)
    else:
        lines.append("@app.post(")
        lines.extend(f'    "{chunk}"' for chunk in path_chunks(path))
        lines.append(")")
    signature = f"async def {name}(request: Request) -> Response:"
    if len(signature) <= LIMIT:
        lines.append(signature)
    else:
        lines.append(f"async def {name}(")
        lines.append("    request: Request,")
        lines.append(") -> Response:")
    args = [f"request, {keys_var}, {op_name}, {fields_literal(fields)}"]
    if wrap:
        args[0] += ", wrap_valid=True"
    oneline = f"    return await _policy_response({args[0]})"
    if len(oneline) <= LIMIT:
        lines.append(oneline)
    else:
        lines.append("    return await _policy_response(")
        lines.append("        request,")
        lines.append(f"        {keys_var},")
        lines.append(f"        {op_name},")
        lines.append(f"        {fields_literal(fields)},")
        if wrap:
            lines.append("        wrap_valid=True,")
        lines.append("    )")
    return "\n".join(lines)


ADAPTER = '''async def _policy_response(
    request: Request,
    keys: set[str],
    operation: Callable[..., Any],
    fields: tuple[str, ...],
    *,
    wrap_valid: bool = False,
) -> Response:
    """Shared HTTP boundary for the stateless policy endpoints.

    Reads the request body, requires an exact key set, invokes the policy
    operation with the requested fields in order, maps ValueError to a 422
    response, and encodes the result as compact UTF-8 JSON.
    """
    try:
        body = json.loads(await request.body())
    except (json.JSONDecodeError, UnicodeDecodeError):
        return _invalid_request()
    if not isinstance(body, dict) or set(body) != keys:
        return _invalid_request()
    try:
        result = operation(*(body[field] for field in fields))
    except ValueError:
        return _invalid_request()
    if wrap_valid:
        result = {"valid": result}
    return _record_response(result)'''

head, rest = source.split('@app.get("/health")', 1)
health_block, tail = rest.split('@app.post("/decisions/{record_id}")', 1)

head = head.replace(
    "import json\nimport os\nfrom typing import Any\n",
    "import json\nimport os\nfrom collections.abc import Callable\nfrom typing import Any\n",
)
assert "from collections.abc import Callable" in head

generated = "\n\n\n".join(emit_endpoint(spec) for spec in specs)

new_source = (
    head
    + ADAPTER
    + "\n\n\n"
    + '@app.get("/health")'
    + health_block
    + generated
    + "\n\n\n"
    + '@app.post("/decisions/{record_id}")'
    + tail
)
APP_PATH.write_text(new_source)
print("wrote", APP_PATH)

