routes_repr = ",\n".join(
    f"    ({path!r},\n     {name!r}, {op!r}, {fields!r}, {wrap!r}),"
    if len(repr((path, name, op, fields, wrap))) > 70
    else f"    ({path!r}, {name!r}, {op!r}, {fields!r}, {wrap!r}),"
    for path, name, _keys, op, fields, wrap in specs
)

