    inner = ", ".join(f'"{f}"' for f in fields)
    if len(fields) == 1:
        inner += ","
    return f"({inner})"


def emit_endpoint(spec):
    path, name, keys_var, op_name, fields, wrap = spec
    lines = []
    decorator = f'@app.post("{path}")'
    if len(decorator) <= LIMIT:
        lines.append(decorator)
    else:
        lines.append("@app.post(")
        lines.extend(f'    "{chunk}"' for chunk in path_chunks(path))
        lines.append(")")
    signature = f"async def {name}(request: Request) -> Response:"
    if len(signature) <= LIMIT:
        lines.append(signature)
    else:
        lines.append(f"async def {name}(")
        lines.append("    request: Request,")
        lines.append(") -> Response:")
    args = [f"request, {keys_var}, {op_name}, {fields_literal(fields)}"]
    if wrap:
        args[0] += ", wrap_valid=True"
    oneline = f"    return await _policy_response({args[0]})"
    if len(oneline) <= LIMIT:
        lines.append(oneline)
    else:
        lines.append("    return await _policy_response(")
        lines.append("        request,")
        lines.append(f"        {keys_var},")
        lines.append(f"        {op_name},")
        lines.append(f"        {fields_literal(fields)},")
        if wrap:
            lines.append("        wrap_valid=True,")
        lines.append("    )")
    return "\n".join(lines)


ADAPTER = '''async def _policy_response(
    request: Request,
    keys: set[str],
    operation: Callable[..., Any],
    fields: tuple[str, ...],
    *,
    wrap_valid: bool = False,
) -> Response:
    """Shared HTTP boundary for the stateless policy endpoints.

    Reads the request body, requires an exact key set, invokes the policy
    operation with the requested fields in order, maps ValueError to a 422
    response, and encodes the result as compact UTF-8 JSON.
    """
    try:
        body = json.loads(await request.body())
    except (json.JSONDecodeError, UnicodeDecodeError):
        return _invalid_request()
    if not isinstance(body, dict) or set(body) != keys:
        return _invalid_request()
    try:
        result = operation(*(body[field] for field in fields))
    except ValueError:
        return _invalid_request()
    if wrap_valid:
        result = {"valid": result}
    return _record_response(result)'''

